        plugins: [hline('lim', function () { return [{ v: CRIT, c: LIM.c, t: '30.5 °C' }, { v: CEIL, c: LIM.t, t: '35 °C', dy: 0 }]; }, true), HH.valueLabels({ axis: 'x', format: function (v) { return v.toFixed(1); } })],
