      plugins: [{ id: 'gm', afterDatasetsDraw: function (ch) { var ctx = ch.ctx, a = ch.chartArea, xs = ch.scales.x; ctx.save(); ctx.font = '10.5px ' + tok('--mono'); MARK.concat([{ v: st.g, t: '', c: INK, solid: true }]).forEach(function (m, j) { var i = Math.round((m.v - 1.2) / 0.05), x = xs.getPixelForValue(i); ctx.strokeStyle = m.c; ctx.fillStyle = m.c; ctx.lineWidth = m.solid ? 2 : 1.3; ctx.setLineDash(m.solid ? [] : [4, 4]); ctx.beginPath(); ctx.moveTo(x, a.top); ctx.lineTo(x, a.bottom); ctx.stroke(); if (m.t) { ctx.save(); ctx.translate(x - 4, a.top + 4); ctx.rotate(-Math.PI / 2); ctx.textAlign = 'right'; ctx.fillText(m.t, 0, 0); ctx.restore(); } }); ctx.restore(); } }],
