      options: { plugins: { legend: { position: 'bottom' }, tooltip: { callbacks: { title: function (c) { var lo = c[0].raw.x - 0.25; return 'Tw ' + lo.toFixed(1) + '–' + (lo + 0.5).toFixed(1) + ' °C'; }, label: function (c) { return c.dataset.label + ': ' + c.raw.y + ' h'; } } } }, scales: { x: Object.assign(axis({ title: 'hourly wet-bulb temperature, °C', grid: false }), { type: 'linear', min: 20, max: 36, ticks: Object.assign({ stepSize: 2, maxRotation: 0 }, tick) }), y: Object.assign(axis({ title: 'hours a year' }), { min: 0 }) } },
      plugins: [{ id: 'hl', afterDatasetsDraw: function (ch) { var ctx = ch.ctx, a = ch.chartArea, xs = ch.scales.x; ctx.save(); [[CRIT, LIM.c], [CEIL, LIM.t]].forEach(function (L) { var x = xs.getPixelForValue(L[0]); ctx.strokeStyle = L[1]; ctx.setLineDash([5, 4]); ctx.lineWidth = 1.6; ctx.beginPath(); ctx.moveTo(x, a.top); ctx.lineTo(x, a.bottom); ctx.stroke(); }); ctx.restore(); } }],
